B.a2P=new A.ah("1. \u5148\u5ba1\u540e\u53d1:\u60a8\u53d1\u5e03\u7684\u4f5c\u54c1\u9700\u7ecf\u5e73\u53f0\u5ba1\u6838,\u5ba1\u6838\u901a\u8fc7\u540e\u624d\u4f1a\u51fa\u73b0\u5728\u793e\u533a\u5e7f\u573a;\u5ba1\u6838\u671f\u95f4\u4f5c\u54c1\u5bf9\u5176\u4ed6\u7528\u6237\u4e0d\u53ef\u89c1,\u60a8\u53ef\u4ee5\u7533\u8bf7\u64a4\u56de\u6216\u5220\u9664\u3002\u79c1\u6709\u4e91\u5907\u4efd\u4e0d\u4f1a\u56e0\u4e0a\u4f20\u800c\u81ea\u52a8\u53d8\u6210\u516c\u5f00\u4f5c\u54c1\u3002",!1)
B.a3S=new A.ah("\u5ba1\u6838\u65b9\u5f0f:\u9488\u5bf9\u6700\u7ec8 GLB,\u5e73\u53f0\u751f\u6210 26 \u5f20\u591a\u89d2\u5ea6\u6a21\u578b\u6e32\u67d3\u56fe,\u59d4\u6258\u963f\u91cc\u4e91\u8fdb\u884c\u6807\u9898\u3001\u63cf\u8ff0\u7684\u6587\u5b57\u5ba1\u6838\u53ca\u5ba1\u6838\u56fe\u7684\u56fe\u7247\u5ba1\u6838\u3002\u8be5\u6d41\u7a0b\u4e0d\u8981\u6c42\u4e0a\u4f20\u539f\u59cb\u62cd\u6444\u7167\u7247\u6216\u62cd\u6444\u8fc7\u7a0b\u6570\u636e\u3002\u673a\u5ba1\u98ce\u9669\u53ef\u8f6c\u4eba\u5de5\u590d\u6838,\u660e\u786e\u8fdd\u89c4\u4e0d\u4e88\u53d1\u5e03,\u670d\u52a1\u5f02\u5e38\u6216\u7ed3\u679c\u4e0d\u5b8c\u6574\u65f6\u4e0d\u4e88\u81ea\u52a8\u516c\u5f00\u3002\u6682\u4e0d\u652f\u6301\u7684\u683c\u5f0f\u4e0d\u80fd\u901a\u8fc7\u8be5\u6d41\u7a0b\u81ea\u52a8\u516c\u5f00;\u4fee\u6539\u5df2\u63d0\u4ea4\u7684\u4f5c\u54c1\u5185\u5bb9\u9700\u8981\u91cd\u65b0\u5ba1\u6838\u3002",!1)
B.a3q=new A.ah("2. \u53d1\u5e03\u5373\u516c\u5f00:\u4f5c\u54c1\u901a\u8fc7\u5ba1\u6838\u540e,\u4f5c\u54c1\u5185\u5bb9\u3001\u60a8\u7684\u6635\u79f0\u3001\u8d26\u53f7 ID \u53ca\u53d1\u5e03\u65f6\u7684 IP \u5c5e\u5730\u5c06\u5bf9\u6240\u6709\u7528\u6237(\u542b\u672a\u767b\u5f55\u8bbf\u5ba2)\u516c\u5f00\u53ef\u89c1\u3002\u516c\u5f00\u53d1\u5e03\u4e0d\u7b49\u4e8e\u653e\u5f03\u9690\u79c1\u6216\u4e2a\u4eba\u4fe1\u606f\u6743\u76ca,\u4e5f\u4e0d\u514d\u9664\u53d1\u5e03\u8005\u53d6\u5f97\u4ed6\u4eba\u6388\u6743\u7684\u4e49\u52a1\u3002IP \u5c5e\u5730\u5c55\u793a\u662f\u6cd5\u5b9a\u8981\u6c42,\u65e0\u6cd5\u5173\u95ed,\u8be6\u89c1\u300a\u65b9\u5bf8\u95f4\u9690\u79c1\u653f\u7b56\u300b\u3002",!0)
B.a4c=new A.ah('3. \u672c\u534f\u8bae\u6240\u79f0"\u5185\u5bb9"\u5305\u62ec\u60a8\u5728\u672c\u670d\u52a1\u4e2d\u4e0a\u4f20\u3001\u53d1\u5e03\u7684\u4e09\u7ef4\u6a21\u578b(\u5982 GLB \u7f51\u683c mesh\u3001PLY \u70b9\u4e91)\u3001\u4e09\u7ef4\u91cd\u5efa\u6570\u636e\u3001\u5c01\u9762\u548c\u884d\u751f\u5ba1\u6838\u56fe\u3001\u6807\u9898\u3001\u63cf\u8ff0\u3001\u8d26\u53f7\u8d44\u6599\u4ee5\u53ca\u5176\u4ed6\u4efb\u4f55\u4fe1\u606f\u3002',!1)
B.a3V=new A.ah("4. \u60a8\u5bf9\u53d1\u5e03\u7684\u5185\u5bb9\u72ec\u7acb\u627f\u62c5\u5168\u90e8\u6cd5\u5f8b\u8d23\u4efb\u3002\u60a8\u4fdd\u8bc1\u5bf9\u53d1\u5e03\u7684\u5185\u5bb9\u4eab\u6709\u5408\u6cd5\u6743\u5229\u6216\u5df2\u53d6\u5f97\u5408\u6cd5\u6388\u6743;\u56e0\u60a8\u53d1\u5e03\u7684\u5185\u5bb9\u5f15\u53d1\u7b2c\u4e09\u65b9\u4e3b\u5f20\u6743\u5229,\u5bfc\u81f4\u5e73\u53f0\u906d\u53d7\u635f\u5931\u7684,\u60a8\u5e94\u5f53\u8d54\u507f\u3002",!1)
B.a4s=new A.ah("\u5220\u9664\u3001\u64a4\u56de\u4e0e\u8bc1\u636e\u7559\u5b58:\u505c\u6b62\u516c\u5f00\u4e0d\u7b49\u4e8e\u6240\u6709\u526f\u672c\u5373\u65f6\u7269\u7406\u64e6\u9664\u3002\u5ba1\u6838\u6750\u6599\u3001\u6295\u8bc9\u7533\u8bc9\u8bc1\u636e\u3001\u6cd5\u5b9a\u7559\u5b58\u53ca\u5386\u53f2\u5907\u4efd\u7684\u9650\u5236\u5904\u7406\u548c\u6e05\u7406,\u6309\u300a\u65b9\u5bf8\u95f4\u9690\u79c1\u653f\u7b56\u300b\u7b2c\u56db\u7ae0\u6267\u884c;\u76f8\u5173\u526f\u672c\u4e0d\u80fd\u56e0\u5907\u4efd\u6062\u590d\u800c\u91cd\u65b0\u516c\u5f00\u3002",!1)
B.a31=new A.ah("5. \u7b2c\u4e09\u65b9\u5c31\u60a8\u53d1\u5e03\u7684\u5185\u5bb9\u5411\u5e73\u53f0\u4e3b\u5f20\u6743\u5229\u65f6,\u5e73\u53f0\u6709\u6743\u4f9d\u6cd5\u5148\u884c\u4e0b\u67b6\u76f8\u5173\u5185\u5bb9\u5e76\u901a\u77e5\u60a8;\u60a8\u53ef\u6309\u7b2c\u516b\u7ae0\u7684\u6e20\u9053\u63d0\u4ea4\u4e0d\u4fb5\u6743\u58f0\u660e\u4e0e\u6743\u5229\u8bc1\u660e\u8fdb\u884c\u7533\u8bc9\u3002",!1)
B.alt=s([B.a2P,B.a3S,B.a3q,B.a4c,B.a3V,B.a4s,B.a31],t.g)
B.a4R=new A.en("\u4e94\u3001\u5185\u5bb9\u53d1\u5e03\u4e0e\u5ba1\u6838",B.alt)
B.a3O=new A.ah("1. \u5e73\u53f0\u8f6f\u4ef6\u53ca\u5176\u6240\u542b\u7684\u754c\u9762\u8bbe\u8ba1\u3001\u7a0b\u5e8f\u4ee3\u7801\u3001\u5546\u6807\u6807\u8bc6\u7b49\u77e5\u8bc6\u4ea7\u6743\u5f52\u6211\u4eec\u6216\u76f8\u5e94\u6743\u5229\u4eba\u6240\u6709\u3002\u672a\u7ecf\u8bb8\u53ef,\u60a8\u4e0d\u5f97\u590d\u5236\u3001\u4fee\u6539\u3001\u4f20\u64ad\u6216\u7528\u4e8e\u4efb\u4f55\u5546\u4e1a\u76ee\u7684\u3002",!1)
B.a3l=new A.ah("2. \u60a8\u5728\u672c\u670d\u52a1\u4e2d\u4e0a\u4f20\u6216\u53d1\u5e03\u7684\u4f5c\u54c1(\u542b\u4e09\u7ef4\u70b9\u4e91\u3001\u7f51\u683c\u6a21\u578b\u53ca\u5176\u884d\u751f\u7684\u5c01\u9762\u4e0e\u5ba1\u6838\u56fe)\u7684\u77e5\u8bc6\u4ea7\u6743\u5f52\u60a8\u6216\u4f9d\u6cd5\u4eab\u6709\u6743\u5229\u7684\u6743\u5229\u4eba\u6240\u6709,\u4e0d\u56e0\u53d1\u5e03\u884c\u4e3a\u800c\u8f6c\u79fb\u3002",!0)
B.a2C=new A.ah("3. \u4e3a\u5411\u60a8\u63d0\u4f9b\u670d\u52a1\u5e76\u6539\u8fdb\u4ea7\u54c1,\u60a8\u6388\u4e88\u5e73\u53f0\u4e00\u9879\u5168\u7403\u8303\u56f4\u5185\u3001\u514d\u8d39\u3001\u975e\u72ec\u5bb6\u7684\u8bb8\u53ef,\u5305\u62ec\u5bf9\u5185\u5bb9\u7684\u590d\u5236\u6743\u3001\u4fe1\u606f\u7f51\u7edc\u4f20\u64ad\u6743\u3001\u6539\u7f16\u6743\u3001\u6c47\u7f16\u6743\u3001\u5c55\u793a\u6743\u53ca\u5236\u4f5c\u884d\u751f\u5185\u5bb9\u7684\u6743\u5229\u3002\u672c\u6b3e\u6240\u79f0\u5185\u5bb9,\u6307\u60a8\u4e0a\u4f20\u81f3\u672c\u670d\u52a1\u7684\u5185\u5bb9,\u5305\u62ec\u53d1\u5e03\u5230\u793e\u533a\u5e7f\u573a\u7684\u4f5c\u54c1,\u4ee5\u53ca\u79c1\u6709\u4e91\u5907\u4efd(\u4e91\u7aef\u5b58\u50a8)\u529f\u80fd\u4e2d\u60a8\u5b58\u50a8\u7684\u5185\u5bb9,\u542b\u4e09\u7ef4\u70b9\u4e91\u3001\u7f51\u683c\u6a21\u578b\u3001\u5c01\u9762\u3001\u884d\u751f\u5ba1\u6838\u56fe\u3001\u6807\u9898\u3001\u63cf\u8ff0\u3002\u4e0a\u8ff0\u6743\u5229\u4ec5\u7528\u4e8e:(1)\u8fd0\u8425\u6240\u5fc5\u9700:\u5b58\u50a8\u3001\u5907\u4efd\u3001\u4f20\u8f93\u3001\u5206\u53d1\u3001\u516c\u5f00\u5c55\u793a(\u4ec5\u9650\u60a8\u9009\u62e9\u516c\u5f00\u53d1\u5e03\u7684\u5185\u5bb9)\u53ca\u683c\u5f0f\u9002\u914d\u3001\u751f\u6210\u5ba1\u6838\u56fe\u3001\u6587\u5b57\u4e0e\u56fe\u7247\u5185\u5bb9\u5b89\u5168\u68c0\u6d4b\u7b49\u6280\u672f\u5904\u7406,\u5e76\u53ef\u5c06\u76f8\u5e94\u5904\u7406\u59d4\u6258\u7ed9\u53d7\u7ea6\u675f\u7684\u4e91\u670d\u52a1\u548c\u5185\u5bb9\u5ba1\u6838\u670d\u52a1\u5546\u6267\u884c;(2)\u5c06\u60a8\u5df2\u516c\u5f00\u53d1\u5e03\u7684\u4f5c\u54c1\u7528\u4e8e\u672c\u4ea7\u54c1\u5404\u7ec8\u7aef\u7248\u672c\u53ca\u5e94\u7528\u5546\u5e97\u9875\u9762\u7684\u5c55\u793a\u4e0e\u63a8\u4ecb;(3)\u6211\u4eec\u5185\u90e8\u7684\u79d1\u5b66\u7814\u7a76\u3001\u6280\u672f\u5f00\u53d1\u4e0e\u6539\u8fdb,\u5305\u62ec\u4f46\u4e0d\u9650\u4e8e\u5404\u7c7b\u4eba\u5de5\u667a\u80fd\u7b97\u6cd5\u4e0e\u6a21\u578b\u7684\u8bad\u7ec3\u3001\u8bc4\u6d4b\u4e0e\u4f18\u5316(\u5982\u4e09\u7ef4\u91cd\u5efa\u76f8\u5173\u7b97\u6cd5\u4e0e\u6a21\u578b),\u4e0d\u8bba\u91c7\u7528\u73b0\u5728\u5df2\u77e5\u6216\u65e5\u540e\u5f00\u53d1\u7684\u6280\u672f\u4e0e\u5f62\u5f0f\u3002",!0)
